import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a rotated quadratic bowl,
    sinusoidal modulation, and pairwise interactions to achieve target ELA features.

    Formula:
    f(x) = rotated_quadratic(x) + sinusoidal_modulation(x) + pairwise_interactions(x)

    Where:
    - rotated_quadratic(x) = 0.5 * (x @ rotation_matrix @ x.T) accounts for the high 'quad_simple' and 'quad_w_interact' adj_r2
    - sinusoidal_modulation(x) = 0.1 * sum(np.sin(2 * np.pi * x)) introduces multi-modality, for 'nbc.nn_nb.sd_ratio' and adjusts skewness of the distribution.
    - pairwise_interactions(x) = 0.05 * sum(x[i] * x[j] for i in range(len(x)) for j in range(i+1, len(x))) enhances interactions as reflected in 'lin_w_interact'.

    The coefficients are adjusted to balance the influence of each component.
    """

    def rotated_quadratic(x):
        """Quadratic bowl with a rotation applied."""
        rotation_matrix = np.array([[0.707, -0.707], [0.707, 0.707]]) # Simple rotation matrix
        return 0.5 * (x @ rotation_matrix @ x.T)

    def sinusoidal_modulation(x):
        """Adds sinusoidal oscillations to the fitness landscape."""
        return 0.1 * np.sum(np.sin(2 * np.pi * x))

    def pairwise_interactions(x):
        """Introduces interactions between variables."""
        interaction_sum = 0.0
        for i in range(len(x)):
            for j in range(i + 1, len(x)):
                interaction_sum += x[i] * x[j]
        return 0.05 * interaction_sum


    return rotated_quadratic(x) + sinusoidal_modulation(x) + pairwise_interactions(x)
